Dropzone.autoDiscover = false;

(function($) {
    /**
     *
     * DROP ZONE
     *
     */
    shelterResourcesDropZone = new Dropzone( '#shelter-resources-upload', {
        url: catspride_params.ajax_url,
        acceptedFiles: 'image/jpeg,image/png',
        maxFilesize: 4,
        rsizeWidth: 800,
        paramName: 'attachment',
        dictDefaultMessage: 'Drag images here or click to upload slideshow images...',
        success: function(file, response){
            if ( response.data.file_name ) {
                $('#shelter-resources-attachments').append('<input type="hidden" name="add_attachments[]" value="' + response.data.file_name +'" />');
            }
        }
    });

    shelterResourcesDropZone.on('sending', function(file, xhr, formData){
        formData.append('nonce', catspride_params._wpnonce);
        formData.append('action', 'cp_edit_shelter_resources_slideshow_uploads');
    });

    $('#shelter-resources-attachments').on('click', '.remove-attachment', function() {
        $('#shelter-resources-attachments').append('<input type="hidden" name="remove_attachments[]" value="' + $(this).data('file_name') + '" />');
        $(this).parents('.attachment-thumbnail').remove();
    });

    jQuery('.shelter-page-header-type-input-wrapper').on('change', 'input[name="page_header_type"]', function() {
        var pageHeaderType = jQuery('input[name="page_header_type"]:checked').val();
        if ( pageHeaderType !== '' ) {
            jQuery('.shelter-page-header-type').hide();
            jQuery('.shelter-page-header-type-' + pageHeaderType ).show();
        }
    });

    jQuery('input[name="page_header_type"]').trigger('change');

    jQuery('ul.x-nav-tabs li').click( function() {
       var tab_id = jQuery(this).attr('id');
       var url = new URL(window.location.href);
       url.searchParams.set('tab', tab_id.replace( 'tab-', '' ) );
       window.history.pushState( null, null, url.toString() );
    });

    jQuery('#cp-copy-shelter-page-url').click( function() {
       var shelter_url = jQuery('#cp-copy-shelter-page-url').data('shelter_url');
       copyTextToClipboard( shelter_url );

       var button_text = jQuery(this).text();
       if ( button_text === 'Copied!' )
           return;
       var button_width = jQuery(this).width();
       jQuery(this).width( button_width ).text('Copied!');

       setTimeout( function( ) {
           jQuery('#cp-copy-shelter-page-url').width( null ).text( button_text );
       }, 2000);
    });

    jQuery('.share-item').hover( function() {
        jQuery(this).find('ul').slideToggle();
    });


    

})(jQuery);


function fallbackCopyTextToClipboard(text) {
    var textArea = document.createElement("textarea");
    textArea.value = text;
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();

    try {
        var successful = document.execCommand('copy');
        var msg = successful ? 'successful' : 'unsuccessful';
        console.log('Fallback: Copying text command was ' + msg);
    } catch (err) {
        console.error('Fallback: Oops, unable to copy', err);
    }

    document.body.removeChild(textArea);
}

function copyTextToClipboard(text) {
    if (!navigator.clipboard) {
        fallbackCopyTextToClipboard(text);
        return;
    }
    navigator.clipboard.writeText(text).then(function() {
        console.log('Async: Copying to clipboard was successful!');
    }, function(err) {
        console.error('Async: Could not copy text: ', err);
    });
}


